#include<bits/stdc++.h>using namespace std; int main(){    int t;    cin >> t;    while(t--)    {        int a;        cin >> a;        string s,su;        cin >> s >> su;        bool found = true;        sort(s.begin(),s.end());        sort(su.begin(),su.end());        for(int i=0;i<a;i++)        {            if(s[i]!=su[i])            {                found = false;                break;            }        }        if(found)        {            cout << "YES" << endl;        }        else        {            cout << "NO" <<endl;        }    }}